sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	// Add your code here
	try {
        var request = new sn_ws.RESTMessageV2('Import Set API Instance A to B', 'Post Method');

        // Always send Instance A's own sys_id so Instance B coalesces on it
        var payLoad = {
            "u_opened_by": current.opened_by.toString(),
            "u_requestor": current.requestor.toString(),
            "u_type_of_asset": current.type_of_asset.toString(),
            "u_consumables": current.consumables.toString(),
            "u_company": current.company.toString(),
            "u_priority": current.priority.toString(),
            "u_short_description": current.short_description.toString(),
            "u_description": current.description.toString(),
            "u_correlation_id": current.getUniqueValue()
        };

        request.setRequestBody(JSON.stringify(payLoad));

        var response = request.execute();
        var httpStatus = response.getStatusCode();
        var responseBody = response.getBody();

        if (httpStatus == 201) {
            var parsedJson = JSON.parse(responseBody);
            var targetResult = parsedJson.result && parsedJson.result[0];

            if (targetResult && targetResult.status == 'updated') {
                gs.info("[Import Set UPDATE] Successfully updated Instance B record. SysID: " + targetResult.sys_id);
            } else {
                gs.error("[Import Set UPDATE] Unexpected transform status. Response: " + responseBody);
            }
        } 
		else{
            gs.error("[Import Set UPDATE] HTTP failure. Status: " + httpStatus + " Response: " + responseBody);
        }
    } 
	catch (ex){
        gs.error("[Import Set UPDATE] Script error: " + ex.getMessage());
    }

})(current, previous);
